function tr(s){var t=s.replace(/\s+/g,' ').trim();if(!t)return null;if(M[t])return s.replace(t,M[t]).replace(/^\s*/,s.match(/^\s*/)[0]);for(var i=0;i<RX.length;i++)if(RX[i][0].test(t))return s.replace(t,t.replace(RX[i][0],RX[i][1]));return null}
function walk(root){if(lang!=='en')return;var w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,null),n,r,a=[];while(n=w.nextNode()){if(n.parentNode&&/^(SCRIPT|STYLE)$/.test(n.parentNode.nodeName))continue;a.push(n)}
 a.forEach(function(n){var v=n.nodeValue;if(!/[А-Яа-яЁё]/.test(v))return;var t=v.replace(/\s+/g,' ').trim();var e=M[t];if(e){n.nodeValue=v.replace(/\S[\s\S]*\S|\S/,e)}else{r=tr(v);if(r)n.nodeValue=r}});
 if(root.querySelectorAll)root.querySelectorAll('[alt],[aria-label],[title]').forEach(function(el){['alt','aria-label','title'].forEach(function(k){var v=el.getAttribute(k);if(v&&M[v.trim()])el.setAttribute(k,M[v.trim()])})})}
function apply(){document.documentElement.lang=lang;if(lang==='en'){var t=document.title.trim();if(M[t])document.title=M[t];walk(document.body)}
 document.querySelectorAll('.lang [data-l]').forEach(function(b){b.classList.toggle('on',b.dataset.l===lang)})}
