function boot(){apply();if(lang==='en'&&window.MutationObserver){var busy=false;new MutationObserver(function(ms){if(busy)return;busy=true;ms.forEach(function(m){if(m.type==='characterData'){var r=tr(m.target.nodeValue);if(r&&r!==m.target.nodeValue)m.target.nodeValue=r}else m.addedNodes.forEach(function(x){if(x.nodeType===3){var r=tr(x.nodeValue);if(r)x.nodeValue=r}else if(x.nodeType===1)walk(x)})});busy=false}).observe(document.body,{childList:true,subtree:true,characterData:true})}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
